#!/usr/bin/env bash
# =============================================================================
# doctor_window_install.sh —— Q2「docker/ipes」定时暂停窗口 一键安装器
#
# 时间（北京时间，每天）：16:45 暂停 → 18:25 恢复（另有每 5 分钟看门狗兜底）
# 自包含：主体脚本已 gzip+base64 内嵌，运行时不二次联网；锁本文件 commit SHA
#         即锁死主体版本。不需要 AK/SK/JWT，不调用任何云 API。
#
#   curl -fsSL '<本文件URL>' | bash                     # 安装（默认动作）
#   curl -fsSL '<本文件URL>' | bash -s -- probe        # 只读体检，不改任何东西
#   curl -fsSL '<本文件URL>' | bash -s -- uninstall    # 卸载：恢复业务 + 删自己 3 条 cron
#   curl -fsSL '<本文件URL>' | bash -s -- install --mode=stop   # 改用 stop 模式
#
# 暂停 = 挂起保活 cron 那一行 + docker pause ipes；恢复 = 还原保活 + unpause。
# 只动 ipes 业务容器，SN / 9 路 / 缓存 / 镜像 / 限速 cron / 其它 cron 行全不动。
# =============================================================================
set -eu
B64=''
BIN="${DOCTOR_BIN:-/usr/local/bin/doctor_window_ctl.sh}"
ACT="${1:-install}"; shift 2>/dev/null || true
case "$ACT" in
  --probe)     ACT=probe ;;
  --uninstall) ACT=uninstall ;;
  --dry-run)   ACT=install; set -- --dry-run "$@" ;;
esac
case "$ACT" in
  install|suspend|resume|watchdog|probe|uninstall) ;;
  *) printf '未知动作: %s（支持 install/suspend/resume/watchdog/probe/uninstall）\n' "${ACT}" >&2; exit 1 ;;
esac

TMP="${BIN}.tmp.$$"
if ! (printf '%s' "$B64" | base64 -d | gzip -d > "$TMP") 2>/dev/null; then
  BIN="/tmp/doctor_window_ctl.sh"; TMP="${BIN}.tmp.$$"
  printf '%s' "$B64" | base64 -d | gzip -d > "$TMP"
fi
# 内容一致就不覆盖，避免 cron 正在执行时被重写
if cmp -s "$TMP" "$BIN"; then rm -f "$TMP"; else mv -f "$TMP" "$BIN"; fi
chmod +x "$BIN" 2>/dev/null || true
export DOCTOR_BIN="$BIN"

if [ "$ACT" = "install" ]; then
  exec bash "$BIN" install --start=16:45 --end=18:25 "$@"
else
  exec bash "$BIN" "$ACT" "$@"
fi
